    /**
     * 将可迭代对象中的元素用指定的分隔符连接成字符串
     * @param charSequence 分隔符
     * @param iterable 包含要连接元素的可迭代对象
     * @return 连接后的字符串
     */
    private String join(CharSequence charSequence, Iterable<?> iterable) {
        Iterator<?> it = iterable.iterator();
        if (!it.hasNext()) {
            return "";
        }
        StringBuilder sb = new StringBuilder();
        sb.append(it.next());
        while (it.hasNext()) {
            sb.append(charSequence);
            sb.append(it.next());
        }
        return sb.toString();
    }

    /**
     * 获取播放器内容的方法
     * 为视频播放构建JSON配置
     * @param str 视频ID
     * @param str2 视频播放URL
     * @param list 其他参数列表
     * @return 包含播放配置的JSON字符串
     * @throws Exception 可能的异常
     */
    public String playerContent(String str, String str2, List<String> list) throws Exception {
        JSONObject jSONObject = new JSONObject();
        jSONObject.put("parse", 1); // 设置为需要解析
        jSONObject.put("jx", "1"); // 设置解析器类型
        jSONObject.put("url", str2); // 设置视频URL
        return jSONObject.toString();
    }

    /**
     * 搜索视频内容的方法
     * 根据关键词从爱奇艺API搜索视频
     * @param str 搜索关键词
     * @param quick 是否快速搜索
     * @return 包含搜索结果的JSON字符串
     * @throws Exception 可能的异常
     */
    public String searchContent(String str, boolean quick) throws Exception {
        // 构建搜索请求URL
        String url = "https://search.video.iqiyi.com/o?if=html5&key=" + str + "&pageNum=1&pos=1&pageSize=20&site=iqiyi";
        // 发送请求并获取响应
        String json = OkHttp.string(url, getHeaders(url));
        // 解析响应中的视频列表
        JSONArray optJSONArray = new JSONObject(json).optJSONObject("data").optJSONArray("docinfos");

        JSONArray videos = new JSONArray();
        // 遍历搜索结果，提取视频信息
        for (int i = 0; i < optJSONArray.length(); i++) {
            JSONObject optJSONObject = optJSONArray.getJSONObject(i).optJSONObject("albumDocInfo");
            JSONObject video = new JSONObject();
            String optString = optJSONObject.optString("albumLink");
            // 构建视频ID（用于获取详情）
            video.put("vod_id", "/albums/album/avlistinfo?aid=" + optJSONObject.optString("qipu_id") + "&size=5000&page=1&url=" + optString);
            video.put("vod_name", optJSONObject.optString("albumTitle"));
            video.put("vod_pic", optJSONObject.optString("albumImg"));
            video.put("vod_remarks", optJSONObject.optString("releaseDate"));
            videos.put(video);
        }
        // 构建返回结果
        JSONObject jSONObject2 = new JSONObject();
        jSONObject2.put("list", videos);
        return jSONObject2.toString();
    }
